/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// TAMRebatePosting table extension
/// </summary>
[ExtensionOf(tableStr(TAMRebatePosting))]
final class METTAMRebatePostingTbl_Extension
{
}

Method.Source:
/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Modified field value for TAMRebatePosting checks the field name modified to perform any business logic
/// </summary>
/// <param name = "_fieldName">TAMRebatePosting field name</param>
/// <param name = "_arrayIndex">The array index of the field</param>
public void modifiedFieldValue(FieldName _fieldName, int _arrayIndex)
{
    TAMRebateDynamicAccount origValue = this.orig().DynamicAccount;

    next modifiedFieldValue(_fieldName, _arrayIndex);

    switch (_fieldName)
    {
        case fieldStr(TAMRebatePosting, METFollowTransItemGSTGroup):
            if (this.METFollowTransItemGSTGroup == NoYes::Yes)
            {
                this.TaxItemGroup = '';
            }
            break;

        // CB705_VendorRebatePosting
        case fieldStr(TAMRebatePosting, DynamicAccount):                
            if (this.DynamicAccount != origValue && this.DynamicAccount == TAMRebateDynamicAccount::METPurchasedFromVendor)
            {
                this.LedgerJournalNameIdRebate = '';
            }
            break;
    }
}

/// <summary>
/// CB705_VendorRebatePosting
/// Validate Metcash purchased from vendor is only used in one scenario as not possible to hide the enum value.
/// </summary>
/// <returns>True if validation successful; otherwize, false.</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (this.DynamicAccount         == TAMRebateDynamicAccount::METPurchasedFromVendor
    && (this.ModuleInventCustVend   != ModuleInventCustVend::Vend
    ||  this.RebatePaymentType      != TAMRebatePaymentType::Vendor
    ||  this.RebatePostingType      != TAMRebatePostingAccountType::CustVend))
    {
        ret = checkFailed("@MET:RebatePostingTableValidation");
    }

    return ret;
}
